const e=[{id:"sv-5-1326",phase:5,topic:"5.3.3",qtype:"concept",difficulty:2,stem:"When should the **response plan** for a newly improved process be written?",options:["Before handover, as part of the control plan, before any failure occurs","After the first out-of-control signal, so it reflects a real failure","After Finance has verified the project savings at closure","During Define, as one section of the project charter"],answer:0,hint:"A response plan says in advance what to do when monitoring signals.",steps:[{title:"Key idea",body:"The response plan is one of the five control-plan elements and is built **before** the team hands the process to the owner."},{title:"Apply",body:"Its value is that the reaction is agreed *before* anything goes wrong, so the first signal is handled without guesswork."},{title:"Eliminate",body:"The charter (Define) and financial verification (end of Control) are the wrong moments."}],final:"Written in advance as part of the control plan → answer **A**",whyWrong:["","Incorrect — waiting for the first signal means nobody knows what to do when it happens; the plan is agreed in advance.","Incorrect — verified financial impact is the last Control step; the response plan must already be in place before handover.","Incorrect — the charter defines the problem and scope; the response plan is a Control-phase element of the control plan."],bookRef:"Book pp. 564, 571"},{id:"sv-5-1327",phase:5,topic:"5.3.3",qtype:"concept",difficulty:2,stem:"What is the purpose of an **escalation exit** in an Out-of-Control Action Plan (OCAP)?",options:["To send every out-of-control point straight to the Champion for approval","To hand the signal to the process owner if no listed cause is found within a set time","To restart the improvement project at the Define phase","To let the operator recalculate the control limits when the checks fail"],answer:1,hint:"Think about what happens when none of the OCAP's listed checks explains the signal.",steps:[{title:"Key idea",body:"A good OCAP lists checks in order; if none of them explains the signal within a time limit, it **escalates** to the process owner for a full investigation."},{title:"Eliminate",body:"Recalculating limits or restarting DMAIC are not escalation; sending everything upward removes front-line action."}],final:"Escalation exit = unresolved signal goes to the process owner → answer **B**",whyWrong:["Incorrect — routing every point upward first defeats immediate front-line action; escalation is only for unresolved signals.","","Incorrect — an unexplained signal needs a full investigation, not a new DMAIC project by default.","Incorrect — failing to find a cause is never a reason to change the limits; limits change only after a documented process change."],bookRef:"Book pp. 544, 571"},{id:"sv-5-1328",phase:5,topic:"5.3.3",qtype:"concept",difficulty:3,stem:"What is the purpose of the **return loop** at the end of an OCAP flowchart?",options:["To check the next sample and go back into the OCAP if the process is still out of control","To return the chart to the Belt so new control limits can be calculated","To repeat the corrective action until the point lies on the centre line","To send the abnormality report back to the operator for signature"],answer:0,hint:"After a correction, the book says to wait for the next sample.",steps:[{title:"Key idea",body:"After correcting, wait for the next sample (p. 548). If it is back in control, stop; if not, **return** to the OCAP."},{title:"Eliminate",body:"Re-adjusting to the centre line is tampering; new limits and signatures are different activities."}],final:"Return loop = verify with the next sample → answer **A**",whyWrong:["","Incorrect — a correction does not justify new limits; limits are recalculated only after a documented process change.","Incorrect — chasing the centre line after the process is back in control is tampering and adds variation.","Incorrect — signing the report is documentation, not the verification loop that confirms the correction worked."],bookRef:"Book pp. 544, 548"},{id:"sv-5-1329",phase:5,topic:"5.3.3",qtype:"concept",difficulty:1,stem:"Which problem does a response plan PRIMARILY prevent?",options:["Slow or inconsistent reaction when monitoring shows a signal","Errors in the measurement system used to collect the data","Choosing the wrong type of control chart for the data","Selecting an improvement that costs more than it saves"],answer:0,hint:"Monitoring detects; what does the response plan add?",steps:[{title:"Key idea",body:"A response plan defines what to do when there is a defect or an out-of-control condition, so people act quickly and in the same agreed way."},{title:"Eliminate",body:"MSA, chart selection and cost-benefit analysis each solve a different problem."}],final:"Response plan prevents slow or improvised reaction → answer **A**",whyWrong:["","Incorrect — measurement error is addressed by MSA in Measure, not by the response plan.","Incorrect — chart selection depends on data type and subgroup size; it is part of the monitoring plan.","Incorrect — cost against benefit is judged in the cost-benefit analysis when solutions are selected."],bookRef:"Book p. 571"},{id:"sv-5-1330",phase:5,topic:"5.3.3",qtype:"concept",difficulty:1,stem:"How is the **'responsibilities'** component of a response plan applied?",options:["By listing the failure modes, usually the highest-risk X's, to check for","By naming who responds to each trigger and who is told or escalated to","By recording proof that the agreed response was actually carried out","By describing the circumstances present when the failure mode occurred"],answer:1,hint:"Each of the five components answers one question: what, which, who, proof, circumstances.",steps:[{title:"Key idea",body:"The five components are triggers, recommended response, responsibilities, documentation and detailed conditions (p. 571)."},{title:"Apply",body:"'Responsibilities' answers **who** responds and who is notified or escalated to."},{title:"Eliminate",body:"The other options describe the triggers, documentation and conditions components."}],final:"Responsibilities = who responds and who is escalated to → answer **B**",whyWrong:["Incorrect — listing the failure modes to check for is the 'triggers' component.","","Incorrect — proof the plan was followed is the 'documentation' component.","Incorrect — the circumstances around the failure are the 'detailed information on the conditions' component."],bookRef:"Book p. 571"},{id:"sv-5-1331",phase:5,topic:"5.3.3",qtype:"concept",difficulty:2,stem:"According to the book, through which tool is the response plan recorded in the **documentation plan**?",options:["FMEA","Pareto chart","Project charter","SIPOC"],answer:0,hint:"Which tool already lists failure modes, causes and current controls?",steps:[{title:"Key idea",body:"The book's documentation plan lists the response plan under the **FMEA**: failure modes, causes and controls become the triggers and actions."},{title:"Eliminate",body:"Pareto, charter and SIPOC are Define/Measure tools with no failure-mode actions."}],final:"Response plan is documented through the FMEA → answer **A**",whyWrong:["","Incorrect — a Pareto chart ranks causes or defect types; it does not hold failure modes, controls and actions.","Incorrect — the charter defines problem, goal and scope in Define; it is not a Control document.","Incorrect — SIPOC scopes the process at high level; it does not list failure modes or responses."],bookRef:"Book pp. 565–570"},{id:"sv-5-1332",phase:5,topic:"5.3.3",qtype:"concept",difficulty:3,stem:"When may a team recalculate the control limits as part of its response to a signal?",options:["After every corrective action, so that the chart starts again from a clean base","Only when a documented process change has altered the process performance","Whenever a point falls outside the limits, to include the latest behaviour","As soon as the abnormality report for the signal has been closed"],answer:1,hint:"Limits describe the process; they change only when the process truly changes.",steps:[{title:"Key idea",body:"New limits are set **only** on signals that performance has changed, and only after the change is documented (pp. 548, 553)."},{title:"Eliminate",body:"Recalculating after a correction, a signal or a closed report all absorb special causes into the limits."}],final:"Recalculate limits only after a documented process change → answer **B**",whyWrong:["Incorrect — a correction usually restores the old process; resetting limits after it hides the next signal.","","Incorrect — absorbing a special cause into the limits widens them and blinds the chart.","Incorrect — closing the paperwork is documentation; it says nothing about whether the process itself has changed."],bookRef:"Book pp. 548, 553"},{id:"sv-5-1333",phase:5,topic:"5.3.3",qtype:"concept",difficulty:1,stem:"According to the book, where does the real **power of SPC** lie?",options:["In calculating the centre line and the control limits correctly","In plotting every data point on a chart displayed at the workplace","In reacting to out-of-control signals by following the OCAP","In comparing each point with the customer specification limits"],answer:2,hint:"A chart that nobody reacts to is wall paper.",steps:[{title:"Key idea",body:"The book (p. 544): the power of SPC is not to find the centre line and limits but to **react** to out-of-control indications with an OCAP."},{title:"Eliminate",body:"Calculating, plotting and comparing with specs are all passive without a response."}],final:"Power of SPC = reacting with the OCAP → answer **C**",whyWrong:["Incorrect — the book says finding the centre line and limits is NOT the power of SPC; reacting is.","Incorrect — a chart that is plotted but never acted on is what the book calls 'wall paper'.","","Incorrect — specification limits do not belong on a control chart; capability is a separate question."],bookRef:"Book p. 544"},{id:"sv-5-1334",phase:5,topic:"5.3.3",qtype:"concept",difficulty:2,stem:"In a well-designed OCAP, who is normally empowered to take **immediate containment** action when the chart signals?",options:["The Champion, after reviewing the signal at the monthly meeting","The Black Belt who coached the original improvement project","The Finance partner who validated the project savings","The trained front-line operator or agent working at the chart"],answer:3,hint:"The book ranks SPC higher when staff are trained AND empowered to stop.",steps:[{title:"Key idea",body:"The book (p. 522) rates SPC higher when staff are trained and **empowered to stop** for special-cause identification."},{title:"Apply",body:"So the OCAP lets the front line contain immediately, while process changes go through the process owner."},{title:"Eliminate",body:"Champion, Black Belt and Finance are not at the chart when the signal appears."}],final:"Front line contains immediately → answer **D**",whyWrong:["Incorrect — waiting for a monthly review delays the response; the Champion sponsors, but does not contain, live signals.","Incorrect — the Belt has moved on after handover; sustaining belongs to the process owner and the team.","Incorrect — Finance verifies benefits; it has no operational role in reacting to a chart signal.",""],bookRef:"Book pp. 522, 544"},{id:"sv-5-1335",phase:5,topic:"5.3.3",qtype:"concept",difficulty:1,stem:"What does the **'documentation that the plan was followed'** component of a response plan provide?",options:["Evidence that the agreed response actually took place","The list of failure modes that the plan watches for","The names of the people who must be told about a signal","The control limits used to decide whether a point signals"],answer:0,hint:"Match the component name to the question it answers.",steps:[{title:"Key idea",body:"The book's fourth component is **documentation that the plan was followed**: proof the response happened, often an abnormality report."},{title:"Eliminate",body:"Triggers, responsibilities and limits are separate parts of the plan."}],final:"Documentation = proof the response happened → answer **A**",whyWrong:["","Incorrect — the failure modes to watch are the 'triggers' component.","Incorrect — who is told or escalated to is the 'responsibilities' component.","Incorrect — control limits are set in the monitoring plan, not in the response documentation."],bookRef:"Book p. 571"},{id:"sv-5-1336",phase:5,topic:"5.3.3",qtype:"concept",difficulty:2,stem:"Which kind of training does the book list as being triggered **by the response plan**?",options:["Orientation training for new hires joining the process","Refresher training when monitoring shows performance degrading","Green Belt certification training for the process owner","Statistics training on how control limits are calculated"],answer:1,hint:"The training plan lists three triggers: new hires, refreshers and one linked to the response plan.",steps:[{title:"Key idea",body:"The book's training plan includes refresher training 'as part of the response plan when monitoring shows performance degrading' (p. 565)."},{title:"Eliminate",body:"Orientation is a separate trigger; certification and limit maths are not response actions."}],final:"Response plan can trigger refresher training → answer **B**",whyWrong:["Incorrect — new-hire orientation is an ongoing-training trigger in its own right, not one raised by a response.","","Incorrect — Belt certification is not part of a process control plan.","Incorrect — operators need to know how to react to a signal, not how to derive the limits."],bookRef:"Book p. 565"},{id:"sv-5-1337",phase:5,topic:"5.3.3",qtype:"concept",difficulty:2,stem:"Why does the book encourage teams to write **notes on the control chart** when a response is carried out?",options:["So the operator can move the control limits to the annotated point","So the notes can replace the abnormality report for that failure","So anyone reading the chart later knows what happened at that point","So the specification limits can be shown next to the control limits"],answer:2,hint:"A chart is a record of the process history, not just today's point.",steps:[{title:"Key idea",body:"The book: 'notes impacting performance on chart should be encouraged' (p. 569). They link a point to its cause and response."},{title:"Eliminate",body:"Notes do not move limits, replace the report or add spec lines."}],final:"Chart notes record what happened → answer **C**",whyWrong:["Incorrect — annotations never justify moving limits; that needs a documented process change.","Incorrect — chart notes are a quick reference; the abnormality report still records cause and prevention.","","Incorrect — specification limits should not be drawn on a control chart at all."],bookRef:"Book p. 569"},{id:"sv-5-1338",phase:5,topic:"5.3.3",qtype:"concept",difficulty:1,stem:"Which phrase BEST describes how the **response plan** differs from the **monitoring plan**?",options:["The monitoring plan names the owner; the response plan sets the sample size","The monitoring plan is temporary; the response plan is permanent","The monitoring plan covers defects; the response plan covers costs","The monitoring plan detects a problem; the response plan says what to do next"],answer:3,hint:"One plan watches; the other acts.",steps:[{title:"Key idea",body:"The monitoring plan defines what, when and how to measure; the response plan starts when monitoring shows a defect or out-of-control condition."},{title:"Eliminate",body:"Sample size belongs to monitoring; both plans are living; costs are a different topic."}],final:"Monitoring detects, response acts → answer **D**",whyWrong:["Incorrect — sample size and frequency are part of the monitoring plan, not the response plan.","Incorrect — both are living documents that are updated as the process changes.","Incorrect — the response plan reacts to defects and out-of-control signals; costs belong to cost-benefit analysis.",""],bookRef:"Book pp. 568, 571"},{id:"sv-5-1339",phase:5,topic:"5.3.3",qtype:"concept",difficulty:3,stem:"A response-plan entry says: *'Trigger: Test 1 on the I chart of activation time. Response: check the provisioning log.'* Which component is still MISSING?",options:["Responsibilities","Triggers","Recommended response","Monitoring frequency"],answer:0,hint:"Check the entry against the five components: which, what, who, proof, circumstances.",steps:[{title:"Key idea",body:"The five components are triggers, recommended response, responsibilities, documentation and detailed conditions."},{title:"Apply",body:"The entry gives the trigger and the action, but nobody is named to act. Of the options, **responsibilities** is missing."},{title:"Eliminate",body:"Monitoring frequency is not a response-plan component."}],final:"No named owner → responsibilities missing → answer **A**",whyWrong:["","Incorrect — the trigger is already stated: Test 1 on the I chart.","Incorrect — the action is already stated: check the provisioning log.","Incorrect — sampling frequency belongs to the monitoring plan, not to the five response components."],bookRef:"Book p. 571"},{id:"sv-5-1340",phase:5,topic:"5.3.3",qtype:"concept",difficulty:1,stem:"Which statement about the response plan is CORRECT?",options:["It is fixed at project closure and changed only by the Champion","It is a living document that is updated as new information arrives","It is used only when a point falls beyond the control limits","It is owned by the Belt after the process is handed over"],answer:1,hint:"Recall the book's description of response plans and who owns them after handover.",steps:[{title:"Key idea",body:"Response plans are **living documents**, updated with new information (p. 571)."},{title:"Eliminate",body:"Each wrong statement has one error: frozen, only beyond-limit points, Belt ownership."}],final:"Response plan = living document → answer **B**",whyWrong:["Incorrect — the book calls response plans living documents; freezing them at closure lets new causes go unhandled.","","Incorrect — non-random patterns within the limits, check-sheet and automation failures are triggers too.","Incorrect — after handover the process owner is accountable; the Belt moves on to other projects."],bookRef:"Book p. 571"},{id:"sv-5-1341",phase:5,topic:"5.3.3",qtype:"concept",difficulty:2,stem:"Which statement about **tampering** is CORRECT?",options:["Adjusting the process quickly after each point reduces variation if the team is trained","Reacting to a point beyond the upper control limit is an example of tampering","Adjusting the process on points that show only common-cause variation increases variation","Tampering is the intended purpose of an Out-of-Control Action Plan"],answer:2,hint:"What happens when you adjust a stable process on every wiggle?",steps:[{title:"Key idea",body:"The book (p. 544): adjusting on every point that is not on the centre line **increases** variation; respond only to rule-based signals."},{title:"Eliminate",body:"A beyond-limit point is a real signal; the OCAP is the opposite of tampering."}],final:"Tampering on common cause increases variation → answer **C**",whyWrong:["Incorrect — speed and training do not help; reacting to common-cause noise always adds variation.","Incorrect — a point beyond the UCL is a genuine special-cause signal; responding to it is correct.","","Incorrect — an OCAP is used only on real signals; it exists to prevent random adjustments."],bookRef:"Book p. 544"},{id:"sv-5-1342",phase:5,topic:"5.3.3",qtype:"concept",difficulty:3,stem:"Which statement about control-chart signals and **specification (SLA) breaches** is CORRECT?",options:["A specification breach always appears as a point beyond the control limits","A point inside the control limits never needs any response from the team","Specification limits should be used as the control limits on the chart","A point can signal a special cause while the SLA is still being met"],answer:3,hint:"Voice of the process (control limits) vs voice of the customer (specification).",steps:[{title:"Key idea",body:"A special-cause signal says the process changed; a spec breach says the customer was let down. They are independent."},{title:"Apply",body:"So a signal can appear while the SLA is met. That is an early warning, and the response plan should route the two cases differently."},{title:"Eliminate",body:"The other statements merge control and specification limits."}],final:"Signal and spec breach are independent → answer **D**",whyWrong:["Incorrect — control limits come from process data, not from the SLA; a stable but incapable process breaches inside its limits.","Incorrect — a spec breach inside the limits still needs customer containment, and patterns within limits are triggers.","Incorrect — the book warns never to plot specification limits as control limits; they answer different questions.",""],trap:"Do not wait for an SLA breach before responding; the chart signal is the early warning.",bookRef:"Book pp. 524, 571"},{id:"sv-5-1343",phase:5,topic:"5.3.3",qtype:"concept",difficulty:2,stem:"Which statement about an **OCAP** is CORRECT?",options:["Its checks are listed in order, starting with the most likely and easiest causes","It is applied to every point that is not exactly on the centre line","It replaces the control chart once the process is stable","It is written by the operator after the first signal has occurred"],answer:0,hint:"An OCAP is a flowchart attached to the chart.",steps:[{title:"Key idea",body:"An OCAP is a flowchart attached to a control chart, listing checks and actions **in order**."},{title:"Eliminate",body:"It is not for every point, does not replace the chart and is not written after the fact."}],final:"OCAP = ordered checks attached to the chart → answer **A**",whyWrong:["","Incorrect — using the OCAP on common-cause points is tampering; it is used only on real signals.","Incorrect — the OCAP is attached to the chart; without the chart nothing triggers it.","Incorrect — the OCAP is agreed in advance as part of the response plan, not improvised after the event."],bookRef:"Book pp. 544, 547"},{id:"sv-5-1344",phase:5,topic:"5.3.3",qtype:"concept",difficulty:3,stem:"Which statement about **verifying a correction** is CORRECT?",options:["Adjustments continue until the plotted point lies on the centre line","If the next sample is back in control, no more changes are made, even above the centre line","The correction is confirmed as soon as the corrective action is completed","The control limits are recalculated straight after the correction is verified"],answer:1,hint:"Book p. 548: wait for the next sample, then stop.",steps:[{title:"Key idea",body:"After a correction, wait for the next sample. If the process is back in control, **DO NOT** make more changes, even if the point is above the centre line (p. 548)."},{title:"Eliminate",body:"Chasing the centre line, skipping verification or resetting limits all break this rule."}],final:"Back in control → stop changing → answer **B**",whyWrong:["Incorrect — chasing the centre line on an in-control process is tampering and adds variation.","","Incorrect — the book says to wait for the next sample before declaring the correction worked.","Incorrect — a correction normally restores the old process, so the existing limits remain valid."],bookRef:"Book p. 548"},{id:"sv-5-1345",phase:5,topic:"5.3.3",qtype:"statements",difficulty:2,stem:`Which statements about **decision rights** in an OCAP are CORRECT?

1. Front-line staff should be empowered to stop for special-cause investigation.
2. Any operator may recalculate the control limits after making a correction.
3. Only the Champion may take containment action for customer impact.
4. Permanent process changes should be approved by the process owner.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Ask who may contain, who may change the process and who may change the limits.",steps:[{title:"Key idea",body:"The book ranks SPC higher when staff are trained and empowered to stop (p. 522). Process changes go through the process owner."},{title:"Apply",body:"1 and 4 are true. 2 is wrong because limits change only after a documented change. 3 is wrong because containment is immediate and front-line."}],final:"1 and 4 are correct → answer **D**",whyWrong:["Incorrect — includes 1 (correct) but also 2: limits are recalculated only after a documented process change, not by any operator.","Incorrect — 2 and 3 are both wrong: operators may not reset limits, and containment is a front-line action.","Incorrect — includes 4 (correct) but also 3: waiting for the Champion delays containment.",""],bookRef:"Book pp. 522, 544"},{id:"sv-5-1346",phase:5,topic:"5.3.3",qtype:"statements",difficulty:2,stem:`Which statements about the response plan's place in the control plan are CORRECT?

1. The response plan replaces the monitoring plan once charts are stable.
2. The response plan is one of the five elements of the control plan.
3. The book's Control roadmap shows developing and implementing the response plan as separate steps.
4. Once the response plan is written, the people using it need no training on it.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Five elements: training, documentation, monitoring, response, aligning systems.",steps:[{title:"Key idea",body:"The response plan is one of five control-plan elements (p. 564). The roadmap lists 'Develop Response Plan' and 'Implement Response Plan' separately (p. 578)."},{title:"Apply",body:"2 and 3 are true. 1 is wrong because monitoring is still needed to detect signals. 4 is wrong because the response must be trained."}],final:"2 and 3 are correct → answer **B**",whyWrong:["Incorrect — includes 2 (correct) but also 1: monitoring detects and response acts, so both are needed.","","Incorrect — includes 3 (correct) but also 4: the book says response to poor results must be part of training.","Incorrect — 1 and 4 are both wrong: the plans work together, and response must be trained."],bookRef:"Book pp. 564, 571, 578"},{id:"sv-5-1347",phase:5,topic:"5.3.3",qtype:"statements",difficulty:3,stem:`Which statements about the book's **abnormality report** are CORRECT?

1. It replaces the FMEA once the first failure has been recorded.
2. It is completed only when a customer has raised a complaint.
3. It records the investigation of cause and the corrective action taken.
4. Counting the reports over time shows which failure modes keep returning.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"The report documents each failure: situation, cause, corrective action, root cause and prevention dates.",steps:[{title:"Key idea",body:"The abnormality report gives detailed documentation of each failure: current situation, investigation of cause, corrective action and root-cause analysis (p. 572)."},{title:"Apply",body:"3 and 4 are true; the book notes it lets you collect the frequency of corrective actions. 1 and 2 are wrong."}],final:"3 and 4 are correct → answer **C**",whyWrong:["Incorrect — 1 and 2 are both wrong: the FMEA stays the backbone, and reports cover every failure-mode occurrence.","Incorrect — includes 3 (correct) but also 2: a report is raised for each failure, not only after complaints.","","Incorrect — includes 4 (correct) but also 1: the report feeds the FMEA; it does not replace it."],bookRef:"Book p. 572"},{id:"sv-5-1348",phase:5,topic:"5.3.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Response plans outline the process to follow when there is a defect or an [?] condition from monitoring.`,options:["capable","out-of-control","specified","stable"],answer:1,hint:"Recall the book's one-line definition of a response plan.",steps:[{title:"Key idea",body:"The book (p. 571): response plans outline the process(es) to follow when there is a defect or an **out-of-control** condition from monitoring."},{title:"Eliminate",body:"Capable, specified and stable describe conditions that need no response."}],final:"Defect or out-of-control condition → answer **B**",whyWrong:["Incorrect — a capable process meets its specification; that needs no response.","","Incorrect — 'specified' describes a requirement, not a condition that monitoring reports.","Incorrect — a stable process shows only common-cause variation; reacting to it would be tampering."],bookRef:"Book p. 571"},{id:"sv-5-1349",phase:5,topic:"5.3.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing words in the following sentence.

SPC charts that are posted at the workplace but never reacted to are described in the book as [?].`,options:["background noise","overhead","scrap","wall paper"],answer:3,hint:"The book's image for a chart that decorates the wall.",steps:[{title:"Key idea",body:"The book (p. 522) ranks 'SPC without proper use' as 'WALL PAPER'. Without a response plan, a chart does nothing."},{title:"Eliminate",body:"Noise, overhead and scrap are terms from other topics."}],final:"Unused SPC = wall paper → answer **D**",whyWrong:["Incorrect — 'noise' is used for common-cause variation, not for unused charts.","Incorrect — overhead is a cost term, not the book's word for ignored charts.","Incorrect — scrap is a defective output (correction waste), not an unused chart.",""],bookRef:"Book p. 522"},{id:"sv-5-1350",phase:5,topic:"5.3.3",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

Containment protects the customer while the cause is being found; it is [?] and is not the correction.`,options:["permanent","preventive","statistical","temporary"],answer:3,hint:"Containment, correction and permanent prevention are three different stages.",steps:[{title:"Key idea",body:"Containment (extra staff, rerouting, holding a release) buys time. It is **temporary**; the special cause still has to be found and removed."},{title:"Eliminate",body:"Permanent and preventive describe later stages; 'statistical' is not about the action."}],final:"Containment is temporary → answer **D**",whyWrong:["Incorrect — a permanent fix removes the cause; containment only limits the damage meanwhile.","Incorrect — prevention stops the cause returning (for example a poka-yoke); containment comes earlier.","Incorrect — containment is an operational action, not a statistical test or calculation.",""],bookRef:"Book pp. 544, 572"},{id:"sv-5-1351",phase:5,topic:"5.3.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A response is needed when the chart shows non-random behaviour [?] the control limits, even if no point is beyond them.`,options:["above","below","outside","within"],answer:3,hint:"The book's second trigger is about patterns that stay inside the lines.",steps:[{title:"Key idea",body:"The book's trigger list includes 'non-random behaviour **within** the control limits' (p. 571): runs, trends, zone patterns."},{title:"Eliminate",body:"Above, below and outside all describe the first trigger, a point beyond a limit."}],final:"Non-random behaviour within the limits → answer **D**",whyWrong:["Incorrect — 'above' the limits describes an out-of-control point, which is a separate trigger.","Incorrect — 'below' the limits is also an out-of-control point, the first trigger in the list.","Incorrect — 'outside' repeats the first trigger; the sentence states that no point is beyond the limits.",""],bookRef:"Book p. 571"},{id:"sv-5-1352",phase:5,topic:"5.3.3",qtype:"not-except",difficulty:1,stem:"Which check would NOT normally appear in the decision diamonds of an OCAP?",options:["Is the data for the signalling point valid?","Was there a known event, such as a planned change or outage?","Has the project charter been signed by the Champion?","Are the vital X's from Analyze inside their operating windows?"],answer:2,hint:"OCAP diamonds are yes/no checks about the signal and its likely causes.",steps:[{title:"Key idea",body:"OCAP diamonds check, in order: is the data valid, was there a known event, are the vital X's in their windows."},{title:"Apply",body:"The charter is a Define document. It has nothing to do with explaining today's signal."}],final:"Charter sign-off is not an OCAP check → answer **C**",whyWrong:["Incorrect — checking the data first is a standard OCAP diamond; a broken feed can fake a signal.","Incorrect — known events are an early, easy check in a good OCAP.","","Incorrect — checking the vital X's links the response to the causes proven in Analyze."],bookRef:"Book pp. 544, 547"},{id:"sv-5-1353",phase:5,topic:"5.3.3",qtype:"not-except",difficulty:3,stem:"A spike in failed eSIM activations triggers the response plan. Which action is NOT a **containment** action?",options:["Moving extra agents to the activation support queue","Notifying affected enterprise customers of the delay","Routing new activations to the backup provisioning platform","Rewriting the provisioning software so the defect can never recur"],answer:3,hint:"Containment protects the customer now; correction and prevention deal with the cause.",steps:[{title:"Key idea",body:"Containment is temporary protection while the cause is investigated."},{title:"Apply",body:"Rewriting the software to stop recurrence is **permanent prevention**. It is valuable, but it is not containment."},{title:"Eliminate",body:"Extra agents, notification and rerouting are all temporary protections."}],final:"Software rewrite = prevention, not containment → answer **D**",whyWrong:["Incorrect — adding agents protects customers now while the cause is found; that is containment.","Incorrect — informing affected customers limits the impact immediately; that is containment.","Incorrect — switching to the backup platform is a temporary workaround; that is containment.",""],trap:"Containment, correction and prevention are different stages. The NOT item hides the later stage among the containment actions.",bookRef:"Book pp. 544, 572"},{id:"sv-5-1354",phase:5,topic:"5.3.3",qtype:"not-except",difficulty:2,stem:"A response plan records 'detailed information on the conditions' when a failure mode occurs. Which entry would NOT belong there?",options:["The name of the Champion who approved the project charter","The shift and team on duty when the failure occurred","The change tickets raised in the 24 hours before the failure","The ticket volume being handled at the time of the failure"],answer:0,hint:"Conditions = the circumstances around the failure, not project history.",steps:[{title:"Key idea",body:"The fifth component records the circumstances present when the failure mode occurred (p. 571)."},{title:"Apply",body:"Shift, recent changes and volume describe those circumstances. The charter approver is project history, not a failure condition."}],final:"Charter approver is not a failure condition → answer **A**",whyWrong:["","Incorrect — who was on duty is a circumstance that may explain the failure.","Incorrect — recent changes are one of the most useful circumstances to record.","Incorrect — volume at the time is a condition that can reveal load-related causes."],bookRef:"Book p. 571"},{id:"sv-5-1355",phase:5,topic:"5.3.3",qtype:"not-except",difficulty:2,stem:"A service-desk response plan lists the triggers below. Which one is NOT an appropriate trigger?",options:["Two of three points beyond 2 sigma on the same side of the centre line","Any day on which the ticket backlog is above the centre line","The automatic ticket-assignment rule is found to be disabled","The daily 'backup verified' checklist item is not ticked"],answer:1,hint:"Being above the centre line on its own is common-cause variation.",steps:[{title:"Key idea",body:"Triggers include OOC points, non-random patterns, proven defect conditions, check-sheet failures and automation failures."},{title:"Apply",body:"About half of all points sit above the centre line by chance. Reacting to them is tampering (p. 544)."}],final:"Above the centre line is not a trigger → answer **B**",whyWrong:["Incorrect — two of three beyond 2 sigma is non-random behaviour within the limits, a listed trigger.","","Incorrect — a disabled assignment rule is an automation failure, a listed trigger.","Incorrect — an unticked checklist item is a check-sheet failure, a listed trigger."],bookRef:"Book pp. 544, 571"},{id:"sv-5-1356",phase:5,topic:"5.3.3",qtype:"scenario",difficulty:1,stem:"The p chart of failed number ports signals at 09:00. Before taking any action, the desk lead checks whether the point was caused by a three-hour outage of the timestamp data feed. Which response activity is the desk lead carrying out?",options:["Containing the impact","Correcting the cause","Verifying the signal","Verifying the correction"],answer:2,hint:"What should be checked before chasing the process?",steps:[{title:"Key idea",body:"A good response starts by checking that the data are right; a broken feed can fake a spike."},{title:"Apply",body:"Checking the feed before acting is **verifying the signal**."},{title:"Eliminate",body:"Containment, correction and verification of the correction all come later."}],final:"Checking the data first = verifying the signal → answer **C**",whyWrong:["Incorrect — containment protects customers, for example extra staff or holding ports; no customer action is taken here.","Incorrect — correcting means removing a proven special cause; the cause is not yet known.","","Incorrect — verifying the correction happens after a fix, using the next sample."],bookRef:"Book pp. 544, 571"},{id:"sv-5-1357",phase:5,topic:"5.3.3",qtype:"scenario",difficulty:1,stem:"A call centre's I chart of call response time has a sticky note on it: *'If response time is too high, get an additional person on the phone bank.'* What is this note an example of?",options:["A monitoring plan","A training plan","An abnormality report","An Out-of-Control Action Plan"],answer:3,hint:"The book's simplest example of a reaction attached to a chart.",steps:[{title:"Key idea",body:"The book (p. 544) uses exactly this note as its example of an **OCAP**: the action to take when the chart signals."},{title:"Eliminate",body:"Abnormality report = record afterwards; monitoring and training plans are other control-plan elements."}],final:"Action attached to the chart = OCAP → answer **D**",whyWrong:["Incorrect — a monitoring plan says what to measure and how often, not what to do on a signal.","Incorrect — a training plan says who is trained and when; it does not attach actions to a chart.","Incorrect — an abnormality report records a failure after it occurs; the note gives the action in advance.",""],bookRef:"Book p. 544"},{id:"sv-5-1358",phase:5,topic:"5.3.3",qtype:"scenario",difficulty:2,stem:"A network operations centre's packet-loss chart signals. The operator fails over traffic to the backup link, but then starts to redesign the routing policy herself. The process owner says routing changes need change control. Which response-plan component should have made this clear?",options:["Detailed conditions","Documentation","Responsibilities","Triggers"],answer:2,hint:"Who may contain, and who may change the process?",steps:[{title:"Key idea",body:"The responsibilities component names who responds, who decides and who is escalated to."},{title:"Apply",body:"Failing over is front-line containment; redesign belongs to the process owner. That split of **decision rights** belongs in responsibilities."}],final:"Decision rights live in responsibilities → answer **C**",whyWrong:["Incorrect — conditions record the circumstances of the failure, not who may decide what.","Incorrect — documentation proves the response was carried out; it does not set decision rights.","","Incorrect — the trigger (the signal) worked; the confusion is about who may change the process."],bookRef:"Book p. 571"},{id:"sv-5-1359",phase:5,topic:"5.3.3",qtype:"scenario",difficulty:2,stem:"After a routing-rule error caused a chart signal, the team rolls the rule back and adds a validation check to the change procedure. They also lower the occurrence rating of 'routing change error' in the FMEA and add the new control to the control plan. What are these last two actions?",options:["Containing the customer impact of the signal","Verifying that the signal was real","Recalculating the control limits after the change","Updating the living documents after the response"],answer:3,hint:"The response plan, FMEA and control plan are all living documents.",steps:[{title:"Key idea",body:"After correcting, the team updates the FMEA (reassessing RPNs) and the control plan, so the documents stay current (pp. 569–570)."},{title:"Eliminate",body:"Containment and verification of the signal come earlier; no limits are recalculated."}],final:"FMEA and control-plan updates = keeping documents living → answer **D**",whyWrong:["Incorrect — containment protects customers during the incident; these updates come after the correction.","Incorrect — verifying the signal is the first step, checking the data before acting.","Incorrect — the FMEA and control plan are updated; the chart limits are not touched.",""],bookRef:"Book pp. 569–570"},{id:"sv-5-1360",phase:5,topic:"5.3.3",qtype:"scenario",difficulty:2,stem:"In a data centre, each time the chart of failed backups signals, the on-call engineer does whatever seems best. Responses differ from night to night and some make things worse. The plan names the trigger and the on-call role. What is MOST clearly missing?",options:["A recommended response for each failure mode","A trigger linked to the highest-risk X's","A named person responsible for responding","A control chart to detect the failures"],answer:0,hint:"The plan says when and who, but not what.",steps:[{title:"Key idea",body:"The recommended response says exactly what to do for each failure mode, so different people react the same way."},{title:"Apply",body:"Trigger and role are present; the agreed **action** is missing, so each engineer improvises."}],final:"Missing the agreed action = recommended response → answer **A**",whyWrong:["","Incorrect — the trigger already exists; the chart signals as it should.","Incorrect — the on-call engineer is already named; the problem is what they do.","Incorrect — the chart is already in place and signalling; detection is working."],bookRef:"Book p. 571"},{id:"sv-5-1361",phase:5,topic:"5.3.3",qtype:"scenario",difficulty:3,stem:"A Black Belt hands over a billing project. SOPs are updated, I-MR charts are posted at the desk and the team is trained. Two months later the chart signals and the team spends a week arguing about what to do. Which control-plan element was overlooked?",options:["Documentation plan","Monitoring plan","Response plan","Training plan"],answer:2,hint:"Detection worked; the reaction did not.",steps:[{title:"Key idea",body:"The control plan has five elements: training, documentation, monitoring, response and aligning systems."},{title:"Apply",body:"The chart detected the problem, but nobody knew what to do. The **response plan** was overlooked."},{title:"Eliminate",body:"SOPs, charts and training are each shown to exist in the scenario."}],final:"Signal detected, no agreed reaction → response plan missing → answer **C**",whyWrong:["Incorrect — the SOPs were updated, so documentation was covered.","Incorrect — the charts were posted and signalled, so monitoring worked.","","Incorrect — the team was trained; what was missing was the agreed action on a signal."],trap:"Overlooking the response plan is a classic trap: charts without a response are 'wall paper'.",bookRef:"Book pp. 564, 571"},{id:"sv-5-1362",phase:5,topic:"5.3.3",qtype:"best-action",difficulty:3,stem:"A routing rule was rolled back after a signal on the MTTR chart. The next five daily points are all inside the limits with no tests failed, but today's point is above the centre line. The team lead cuts night-shift staffing by one more engineer to 'pull it back to the centre'. Was this an appropriate action?",options:["Yes, because a point above the centre line shows the process is drifting","Yes, because the response continues until the point is on the centre line","No, because once the process is back in control no further changes are made","No, because the control limits must be recalculated before any change"],answer:2,hint:"Book p. 548 on what to do after the process is back in control.",steps:[{title:"Key idea",body:"After a correction, if the process is back in control, the book says 'DO NOT make any more changes', even above the centre line (p. 548)."},{title:"Apply",body:"Five in-control points and no tests failed means stable. The extra cut is tampering."},{title:"Eliminate",body:"Recalculating limits is not the issue here."}],final:"Back in control → no more changes → answer **C**",whyWrong:["Incorrect — one point above the centre line is common-cause variation, not drift; no test has failed.","Incorrect — the book says the opposite: once back in control, stop changing.","","Incorrect — no documented process change justifies new limits; the problem is the extra adjustment itself."],bookRef:"Book p. 548"},{id:"sv-5-1363",phase:5,topic:"5.3.3",qtype:"best-action",difficulty:3,stem:"After a Test 1 signal on the chart of failed payments was traced to a gateway fault and corrected, the Belt recalculates the control limits using all the data, including the signal point, 'to reflect the new reality'. Was this an appropriate action?",options:["Yes, because the limits should always include the latest data","Yes, because a signal shows that the process has permanently changed","No, because limits are recalculated only after a documented process change","No, because limits may be recalculated only by the Champion"],answer:2,hint:"When are new control limits justified?",steps:[{title:"Key idea",body:"New limits are set only when performance has genuinely changed and the change is documented (pp. 548, 553)."},{title:"Apply",body:"A corrected fault restores the old process. Folding the signal into the limits widens them and blinds the chart."}],final:"No documented change → keep the limits → answer **C**",whyWrong:["Incorrect — including a special cause inflates the limits and hides the next signal.","Incorrect — the gateway fault was corrected, so the old process was restored, not changed.","","Incorrect — the rule is about evidence of a documented change, not about the role of the Champion."],trap:"Recalculating limits after a signal is an over-reaction; it is not a response.",bookRef:"Book pp. 548, 553"},{id:"sv-5-1364",phase:5,topic:"5.3.3",qtype:"best-action",difficulty:2,stem:"A Test 1 signal appears on the chart of failed card payments. The data feed has been confirmed valid. Customers are failing to pay right now and the cause is not yet known. What is the BEST next action under the response plan?",options:["Wait for several more points to confirm whether a trend is forming","Contain the impact, for example by routing payments to the backup gateway, while the cause is investigated","Recalculate the control limits to include the new behaviour","Close the signal and record it in next month's performance report"],answer:1,hint:"Signal verified, customers affected, cause unknown — what comes next?",steps:[{title:"Key idea",body:"The response sequence is: verify → contain → notify/escalate → investigate → correct → verify → document → update."},{title:"Apply",body:"The signal is verified, so the next step is to **contain** the customer impact while investigating."}],final:"Verified signal + customer impact → contain → answer **B**",whyWrong:["Incorrect — a Test 1 point is already a signal; the book says respond immediately to special causes.","","Incorrect — new limits are justified only by a documented process change, not by a signal.","Incorrect — delaying to a monthly report leaves customers failing; the response must happen now."],bookRef:"Book pp. 544, 571"},{id:"sv-5-1365",phase:5,topic:"5.3.3",qtype:"best-action",difficulty:2,stem:"All points on the I chart of ticket resolution time are inside the limits and no tests have failed. The manager asks the analyst to 'run the OCAP anyway, to be safe' and adjust the triage settings. The analyst declines. Was declining an appropriate action?",options:["Yes, because with no special cause the OCAP is not used and no action is taken","Yes, because only the Champion is allowed to start an OCAP","No, because the OCAP should be run at every performance review","No, because small adjustments keep the process close to target"],answer:0,hint:"What does the book say to do when no special cause is present?",steps:[{title:"Key idea",body:"With no special cause the OCAP is not used and no action is taken. Adjusting anyway increases variation (p. 544)."},{title:"Apply",body:"Every point is in control and no tests failed, so declining is correct."}],final:"No signal → no OCAP, no adjustment → answer **A**",whyWrong:["","Incorrect — the OCAP is started by the trigger, not by a particular role.","Incorrect — the OCAP is triggered by signals, not by the meeting calendar.","Incorrect — adjusting a stable process is tampering and increases variation."],bookRef:"Book p. 544"},{id:"sv-5-1366",phase:5,topic:"5.3.3",qtype:"output",difficulty:2,stem:`The monitoring chart for daily dropped-call rate gives:

\`\`\`
Test Results for I Chart of Dropped-Call Rate (%)

TEST 5. 2 out of 3 points more than 2 standard deviations from center
        line (on one side of CL).
Test Failed at points:  23

No points beyond the control limits.
\`\`\`

Which response-plan trigger does this output represent?`,options:["An out-of-control point beyond a control limit","A check-sheet failure","Non-random behaviour within the control limits","A specification breach"],answer:2,hint:"Test 5 is a zone pattern; check where the points lie relative to the limits.",steps:[{title:"Read",body:"Test 5 failed at point 23, and no point is beyond the limits."},{title:"Apply",body:"A zone pattern inside the limits is the trigger 'non-random behaviour **within** the control limits'."},{title:"Eliminate",body:"No beyond-limit point, no checklist and no spec comparison appear."}],final:"Test 5 = non-random behaviour within limits → answer **C**",whyWrong:["Incorrect — the output states that no point is beyond the limits.","Incorrect — a check-sheet failure is a missed checklist item, not a chart pattern.","","Incorrect — the output compares points with sigma zones, not with a customer specification."],bookRef:"Book pp. 532, 571"},{id:"sv-5-1367",phase:5,topic:"5.3.3",qtype:"output",difficulty:3,stem:`An Xbar-R chart monitors fibre splice loss (subgroups of 4). The session shows:

\`\`\`
Test Results for R Chart of Splice Loss

TEST 1. One point more than 3.00 standard deviations from center line.
Test Failed at points:  14

Test Results for Xbar Chart of Splice Loss

No tests failed.
\`\`\`

Should the response plan be activated?`,options:["No, because the Xbar chart shows the average is still in control","No, because the R chart only shows measurement error","Yes, but only after the Xbar chart also shows a signal","Yes, because an out-of-control point on the R chart is a trigger"],answer:3,hint:"Which chart of an Xbar-R pair is read first, and is a point on it a trigger?",steps:[{title:"Read",body:"The R chart failed Test 1 at subgroup 14; the Xbar chart shows no failures."},{title:"Apply",body:"An out-of-control point on **either** chart is a trigger. The R chart signal means within-subgroup variation changed."},{title:"Eliminate",body:"A stable average does not cancel a range signal."}],final:"R chart OOC point → activate the response → answer **D**",whyWrong:["Incorrect — the R chart is read first; an out-of-control range is a signal even when the mean looks stable.","Incorrect — the R chart tracks within-subgroup process variation, not just gauge error.","Incorrect — waiting for a second chart delays the response; one OOC point is already a trigger.",""],bookRef:"Book pp. 519, 571"},{id:"sv-5-1368",phase:5,topic:"5.3.3",qtype:"output",difficulty:2,stem:`The abnormality-report log for failed installations shows:

\`\`\`
Date    Signal       Cause code   Corrective action        Permanent prevention date
02-Mar  Test 1, pt 8  CC-04        Re-provisioned ONT       15-Mar
14-Mar  Test 2, pt 31 CC-11        Reassigned port          (blank)
27-Mar  Test 1, pt 52 CC-04        Re-provisioned ONT       15-Apr
\`\`\`

Which section of the abnormality report is incomplete for 14-Mar?`,options:["Root-cause analysis","Current situation","Investigation of cause","Corrective action"],answer:0,hint:"Match each column to the report section it belongs to.",steps:[{title:"Key idea",body:"The book's report has current situation, investigation of cause and corrective action, then root-cause analysis with a date for permanent prevention (p. 572)."},{title:"Read",body:"On 14-Mar only the permanent-prevention date is blank, so the **root-cause analysis** section is incomplete."}],final:"Blank prevention date → root-cause analysis incomplete → answer **A**",whyWrong:["","Incorrect — the signal and date (current situation) are filled in for 14-Mar.","Incorrect — a cause code CC-11 is recorded, so the investigation of cause is present.","Incorrect — 'Reassigned port' is recorded as the corrective action."],bookRef:"Book p. 572"},{id:"sv-5-1369",phase:5,topic:"5.3.3",qtype:"output",difficulty:1,stem:`The P chart of P2 SLA breaches fails Test 1 at point 37. The response-plan entry reads:

\`\`\`
RP-03  Trigger:  Test 1 or Test 5 on P chart of P2 SLA breaches
       Contain:  Desk lead moves two engineers from the P3 queue
       Investigate: Incident manager, paged within 15 minutes
       Approve process change: Process owner
       Record:   Abnormality report in the ticket tool
\`\`\`

Who should investigate the root cause of the point 37 signal?`,options:["The desk lead","The incident manager","The P3 queue engineers","The process owner"],answer:1,hint:"Read the row for 'Investigate'.",steps:[{title:"Read",body:"RP-03 assigns 'Investigate' to the **incident manager**, paged within 15 minutes."},{title:"Eliminate",body:"Desk lead = contain, process owner = approve change, P3 engineers = extra capacity."}],final:"Investigate row → incident manager → answer **B**",whyWrong:["Incorrect — the desk lead contains the impact; investigation is assigned to another role.","","Incorrect — the P3 engineers are moved to contain the impact; they are not assigned the investigation.","Incorrect — the process owner approves process changes; investigating is assigned to another role."],bookRef:"Book p. 571"},{id:"sv-5-1370",phase:5,topic:"5.3.3",qtype:"output",difficulty:3,stem:`An I chart of daily activation time shows:

\`\`\`
Test Results for I Chart of Activation Time (min)

TEST 1. One point more than 3.00 standard deviations from center line.
Test Failed at points:  12
\`\`\`

The OCAP's first check finds that point 12 was recorded while the timestamp server clock was wrong. The real activation times for that day were normal. What should the response be?`,options:["Reduce the activation workload so the next point falls back towards the mean","Correct the data record, note it on the chart and make no process adjustment","Recalculate the control limits without point 12 and tighten them","Escalate to the Champion to reopen the improvement project"],answer:1,hint:"The first OCAP diamond asks whether the data are valid.",steps:[{title:"Read",body:"Test 1 at point 12, but the OCAP's data check shows a clock fault, not a process change."},{title:"Apply",body:"Fix the record, annotate the chart and document the cause. No process adjustment is needed."},{title:"Eliminate",body:"Adjusting the process, changing limits or reopening the project all treat a data error as a process signal."}],final:"Invalid data → fix record, no process change → answer **B**",whyWrong:["Incorrect — the process did not change; adjusting it in response to a data error is tampering.","","Incorrect — a data error does not justify new limits; limits change only after a documented process change.","Incorrect — the signal is explained by the measurement, so no project needs to be reopened."],bookRef:"Book pp. 544, 569"},{id:"sv-5-1371",phase:5,topic:"5.3.3",qtype:"output",difficulty:1,stem:`One row of the control plan for incident restoration reads:

\`\`\`
Step        Characteristic          Spec     Method       Owner              Reaction
Restore     Daily mean P2 MTTR (h)  <= 4 h   I-MR chart   Incident manager   RP-07
\`\`\`

What does the entry 'RP-07' in the Reaction column refer to?`,options:["The revision number of the I-MR chart's control limits","The risk priority number of this step in the FMEA","The response-plan entry to follow when this characteristic signals","The report page where the monthly MTTR is published"],answer:2,hint:"Each control-plan row links to its response.",steps:[{title:"Read",body:"The column is headed 'Reaction'. RP-07 is the reaction reference for this row."},{title:"Apply",body:"It points to the **response-plan entry** to follow when the MTTR chart triggers."}],final:"Reaction reference → response-plan entry → answer **C**",whyWrong:["Incorrect — control-limit revisions are not tracked in the Reaction column.","Incorrect — an RPN is a number from severity, occurrence and detection, not a plan reference.","","Incorrect — reporting is part of monitoring and documentation; 'Reaction' points to the response."],bookRef:"Book pp. 564, 571"},{id:"sv-5-1372",phase:5,topic:"5.3.3",qtype:"true-false",difficulty:1,stem:"True or False? The book states that the response to poor process results must be part of training.",options:["True","False"],answer:0,hint:"Recall what the book says about response plans and training.",steps:[{title:"Key idea",body:"The book (p. 571): response to poor process results **must be part of training**."},{title:"Apply",body:"The statement is therefore true."}],final:"Response must be part of training — True → answer **True**",whyWrong:["","Incorrect — the book states this directly, because people must know how to react when monitoring signals."],bookRef:"Book p. 571"},{id:"sv-5-1373",phase:5,topic:"5.3.3",qtype:"sequence",difficulty:2,stem:`A special cause on the chart of failed number ports has been found. Put the remaining response steps in order:

- **P** — Wait for the next sample and confirm the process is back in control
- **Q** — Remove the special cause
- **R** — Update the FMEA and the control plan
- **S** — Complete the abnormality report`,options:["Q → S → R → P","P → Q → S → R","Q → R → P → S","Q → P → S → R"],answer:3,hint:"Correct → verify → document → update.",steps:[{title:"Key idea",body:"After investigation: correct the cause, verify with the next sample (p. 548), document in the abnormality report, then update the FMEA and control plan."},{title:"Apply",body:"Q → P → S → R."}],final:"Correct, verify, document, update → answer **D**",whyWrong:["Incorrect — the documents are completed before the fix is confirmed; the next sample must be checked first.","Incorrect — there is nothing to verify before the cause has been removed.","Incorrect — updating the FMEA before verifying and recording the response is premature.",""],bookRef:"Book pp. 548, 569–572"},{id:"sv-5-1374",phase:5,topic:"5.3.3",qtype:"sequence",difficulty:3,stem:`An OCAP for a latency chart lists these checks. In which order should they appear?

- **P** — Are the vital X's (CPU load, link utilisation) inside their windows?
- **Q** — Is the latency data for the signalling point valid?
- **R** — If no cause is found within 2 hours, escalate to the process owner
- **S** — Was there a known event, such as a planned change or outage?`,options:["Q → S → P → R","S → Q → P → R","Q → P → S → R","P → S → Q → R"],answer:0,hint:"Order checks by likelihood and ease: data first, escalation last.",steps:[{title:"Key idea",body:"OCAP checks run from the easiest and most likely: data valid → known event → vital X's → escalation exit."},{title:"Apply",body:"Q → S → P → R."}],final:"Data → known event → vital X's → escalate → answer **A**",whyWrong:["","Incorrect — checking for known events before confirming the data risks chasing a fake signal.","Incorrect — known events are quicker to check than the vital X's, so they come first.","Incorrect — investigating the vital X's before checking the data and known events wastes effort."],bookRef:"Book pp. 544, 547"},{id:"sv-5-1375",phase:5,topic:"5.3.3",qtype:"sequence",difficulty:2,stem:`Put these parts of the book's Control sequence in order:

- **P** — Response plan
- **Q** — Verified financial impact
- **R** — Monitoring plan
- **S** — Aligning systems and structures`,options:["P → R → S → Q","R → P → S → Q","R → S → P → Q","S → R → P → Q"],answer:1,hint:"Monitoring detects, response reacts, systems make it permanent, then Finance verifies.",steps:[{title:"Key idea",body:"The book's sequence: improvement selected → training → documentation → monitoring → response → align systems → verified financial impact."},{title:"Apply",body:"R → P → S → Q."}],final:"Monitoring, response, aligning, financial impact → answer **B**",whyWrong:["Incorrect — a response cannot be defined before monitoring shows what is being watched.","","Incorrect — the book places response before aligning systems and structures.","Incorrect — aligning systems follows monitoring and response in the book's sequence."],bookRef:"Book p. 564"}];export{e as items};
